package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.leo;

import org.eclipse.rdf4j.common.annotation.Experimental;

/**
 * Conservative LEO confidence state. Recent samples influence correction ratios, while dispersion and q-error constrain
 * trust.
 * <p>
 * Robustness contract (regression-safe learning):
 * <ul>
 * <li>A sample with a non-finite or negative input is invalid and is a no-op: it does not count, does not move any
 * estimate and does not refresh the epoch.</li>
 * <li>Correction ratios are learned as a geometric (log-space) EWMA, so a 100x under-estimate followed by a 100x
 * over-estimate averages to 1 instead of biasing the multiplier.</li>
 * <li>Both sides of a correction ratio are floored at one row, so an empty execution can never correct an estimate
 * below one row.</li>
 * <li>The confidence penalties use a decayed q-error statistic and an EWMA log-variance, so a single outlier fades as
 * accurate samples accumulate; {@link #rowQErrorMax()} / {@link #workQErrorMax()} remain the true historical maxima for
 * diagnostics and uncertainty bounds.</li>
 * <li>Epoch decay uses the absolute epoch distance, so evidence keeps decaying when the epoch counter regresses (store
 * rebuilt, sidecar reset) and a sample from a regressed counter re-anchors the timeline.</li>
 * </ul>
 */
@Experimental
public final class LeoConfidenceModel {

	private static final double EWMA_ALPHA = 0.60d;
	private static final double LOG_VARIANCE_ALPHA = 0.10d;
	private static final double Q_ERROR_DECAY = 0.85d;
	private static final double MIN_CORRECTION_RATIO = 0.000001d;
	private static final double MAX_CORRECTION_RATIO = 100_000.0d;
	private static final double LN_10 = Math.log(10.0d);
	private static final LeoConfidenceModel EMPTY = new LeoConfidenceModel(0L, 1.0d, 1.0d, 1.0d, 1.0d, 1.0d,
			1.0d, 1.0d, 1.0d, 0.0d, 0L, 0.0d);

	private final long sampleCount;
	private final double rowCorrectionRatio;
	private final double workCorrectionRatio;
	private final double rowQErrorMean;
	private final double rowQErrorMax;
	private final double rowQErrorDecayed;
	private final double workQErrorMean;
	private final double workQErrorMax;
	private final double workQErrorDecayed;
	private final double logRatioVariance;
	private final long lastEpoch;
	private final double confidence;

	private LeoConfidenceModel(long sampleCount, double rowCorrectionRatio, double workCorrectionRatio,
			double rowQErrorMean, double rowQErrorMax, double rowQErrorDecayed, double workQErrorMean,
			double workQErrorMax, double workQErrorDecayed, double logRatioVariance, long lastEpoch,
			double confidence) {
		this.sampleCount = sampleCount;
		this.rowCorrectionRatio = rowCorrectionRatio;
		this.workCorrectionRatio = workCorrectionRatio;
		this.rowQErrorMean = rowQErrorMean;
		this.rowQErrorMax = rowQErrorMax;
		this.rowQErrorDecayed = rowQErrorDecayed;
		this.workQErrorMean = workQErrorMean;
		this.workQErrorMax = workQErrorMax;
		this.workQErrorDecayed = workQErrorDecayed;
		this.logRatioVariance = logRatioVariance;
		this.lastEpoch = lastEpoch;
		this.confidence = confidence;
	}

	public static LeoConfidenceModel empty() {
		return EMPTY;
	}

	/**
	 * Restores a persisted model. Every input is sanitized: ratios fall back to 1, q-errors to their coherent bounds,
	 * and a non-finite confidence is recomputed from the restored state.
	 */
	public static LeoConfidenceModel fromPersisted(long sampleCount, double rowCorrectionRatio,
			double workCorrectionRatio, double rowQErrorMean, double rowQErrorMax, double rowQErrorDecayed,
			double workQErrorMean, double workQErrorMax, double workQErrorDecayed, double logRatioVariance,
			long lastEpoch, double confidence) {
		if (sampleCount <= 0L) {
			return empty();
		}
		double safeRowCorrectionRatio = clamp(finitePositiveOr(rowCorrectionRatio, 1.0d), MIN_CORRECTION_RATIO,
				MAX_CORRECTION_RATIO);
		double safeWorkCorrectionRatio = clamp(finitePositiveOr(workCorrectionRatio, 1.0d), MIN_CORRECTION_RATIO,
				MAX_CORRECTION_RATIO);
		double safeRowQErrorMean = finiteQErrorOr(rowQErrorMean, 1.0d);
		double safeRowQErrorMax = Math.max(safeRowQErrorMean, finiteQErrorOr(rowQErrorMax, safeRowQErrorMean));
		double safeRowQErrorDecayed = Math.min(safeRowQErrorMax, finiteQErrorOr(rowQErrorDecayed, safeRowQErrorMax));
		double safeWorkQErrorMean = finiteQErrorOr(workQErrorMean, 1.0d);
		double safeWorkQErrorMax = Math.max(safeWorkQErrorMean, finiteQErrorOr(workQErrorMax, safeWorkQErrorMean));
		double safeWorkQErrorDecayed = Math.min(safeWorkQErrorMax,
				finiteQErrorOr(workQErrorDecayed, safeWorkQErrorMax));
		double safeLogRatioVariance = Double.isFinite(logRatioVariance) && logRatioVariance >= 0.0d
				? logRatioVariance
				: 0.0d;
		double safeConfidence = Double.isFinite(confidence)
				? clamp(confidence, 0.0d, 0.95d)
				: confidence(sampleCount, safeLogRatioVariance, safeRowQErrorDecayed);
		return new LeoConfidenceModel(sampleCount, safeRowCorrectionRatio, safeWorkCorrectionRatio,
				safeRowQErrorMean, safeRowQErrorMax, safeRowQErrorDecayed, safeWorkQErrorMean, safeWorkQErrorMax,
				safeWorkQErrorDecayed, safeLogRatioVariance, Math.max(0L, lastEpoch), safeConfidence);
	}

	/**
	 * Records one execution. Returns {@code this} unchanged when any input is non-finite or negative: an invalid
	 * observation is no evidence at all, neither for nor against the current estimate.
	 */
	public LeoConfidenceModel observe(double estimatedRows, double actualRows, double estimatedWorkRows,
			double actualWorkRows, long epoch) {
		if (!isValidSample(estimatedRows) || !isValidSample(actualRows) || !isValidSample(estimatedWorkRows)
				|| !isValidSample(actualWorkRows)) {
			return this;
		}
		double rowRatio = correctionRatio(estimatedRows, actualRows);
		double workRatio = correctionRatio(estimatedWorkRows, actualWorkRows);
		double rowQError = qError(estimatedRows, actualRows);
		double workQError = qError(estimatedWorkRows, actualWorkRows);
		long nextCount = sampleCount + 1L;

		double nextRowCorrection = sampleCount == 0L ? rowRatio : geometricEwma(rowCorrectionRatio, rowRatio);
		double nextWorkCorrection = sampleCount == 0L ? workRatio : geometricEwma(workCorrectionRatio, workRatio);
		double nextRowQErrorMean = sampleCount == 0L ? rowQError
				: rowQErrorMean + (rowQError - rowQErrorMean) / nextCount;
		double nextWorkQErrorMean = sampleCount == 0L ? workQError
				: workQErrorMean + (workQError - workQErrorMean) / nextCount;
		double nextRowQErrorMax = Math.max(rowQErrorMax, rowQError);
		double nextWorkQErrorMax = Math.max(workQErrorMax, workQError);
		double nextRowQErrorDecayed = sampleCount == 0L ? rowQError
				: Math.max(rowQError, Math.max(1.0d, rowQErrorDecayed * Q_ERROR_DECAY));
		double nextWorkQErrorDecayed = sampleCount == 0L ? workQError
				: Math.max(workQError, Math.max(1.0d, workQErrorDecayed * Q_ERROR_DECAY));

		double nextLogRatioVariance;
		if (sampleCount == 0L) {
			nextLogRatioVariance = 0.0d;
		} else {
			double deviation = Math.log(rowRatio) - Math.log(rowCorrectionRatio);
			nextLogRatioVariance = logRatioVariance * (1.0d - LOG_VARIANCE_ALPHA)
					+ deviation * deviation * LOG_VARIANCE_ALPHA;
		}

		double nextConfidence = confidence(nextCount, nextLogRatioVariance, nextRowQErrorDecayed);
		return new LeoConfidenceModel(nextCount, nextRowCorrection, nextWorkCorrection, nextRowQErrorMean,
				nextRowQErrorMax, nextRowQErrorDecayed, nextWorkQErrorMean, nextWorkQErrorMax,
				nextWorkQErrorDecayed, nextLogRatioVariance, Math.max(0L, epoch), nextConfidence);
	}

	public long sampleCount() {
		return sampleCount;
	}

	public double rowCorrectionRatio() {
		return rowCorrectionRatio;
	}

	public double workCorrectionRatio() {
		return workCorrectionRatio;
	}

	public double rowQErrorMean() {
		return rowQErrorMean;
	}

	/** Historical maximum row q-error (never decays; diagnostics and uncertainty bounds). */
	public double rowQErrorMax() {
		return rowQErrorMax;
	}

	/** Row q-error statistic that decays with every valid sample; drives the confidence penalty. */
	public double rowQErrorDecayed() {
		return rowQErrorDecayed;
	}

	public double workQErrorMean() {
		return workQErrorMean;
	}

	/** Historical maximum work q-error (never decays; diagnostics and uncertainty bounds). */
	public double workQErrorMax() {
		return workQErrorMax;
	}

	/** Work q-error statistic that decays with every valid sample. */
	public double workQErrorDecayed() {
		return workQErrorDecayed;
	}

	/** EWMA variance of {@code ln(actual / estimate)} around the learned log-space correction. */
	public double logRatioVariance() {
		return logRatioVariance;
	}

	public long lastEpoch() {
		return lastEpoch;
	}

	public double confidence() {
		return confidence;
	}

	/**
	 * Confidence after age decay. Age is the absolute distance between {@code currentEpoch} and the last observed
	 * epoch: when the counter has moved backwards the timeline is unknown and distance is the only information.
	 */
	public double decayedConfidence(long currentEpoch, long halfLifeEpochs) {
		if (sampleCount <= 0L || confidence <= 0.0d) {
			return 0.0d;
		}
		if (halfLifeEpochs <= 0L || currentEpoch == lastEpoch) {
			return confidence;
		}
		double age = Math.abs((double) currentEpoch - (double) lastEpoch);
		double decay = Math.pow(0.5d, age / (double) halfLifeEpochs);
		return clamp(confidence * decay, 0.0d, confidence);
	}

	private static double confidence(long sampleCount, double logRatioVariance, double qErrorDecayed) {
		if (sampleCount <= 0L) {
			return 0.0d;
		}
		double base = Math.min(0.90d, 0.35d + Math.max(0L, sampleCount - 1L) * 0.075d);
		if (sampleCount == 1L) {
			base = Math.min(base, 0.35d);
		}
		double logSigma = Math.sqrt(Math.max(0.0d, logRatioVariance));
		double variancePenalty = Math.min(0.85d, 0.50d * logSigma / LN_10);
		double qErrorPenalty = qErrorDecayed <= 4.0d ? 0.0d
				: Math.min(0.35d, Math.log10(qErrorDecayed / 4.0d) * 0.20d);
		return clamp(base * (1.0d - variancePenalty) - qErrorPenalty, 0.0d, 0.95d);
	}

	private static double geometricEwma(double previousRatio, double ratio) {
		double logNext = Math.log(previousRatio) * (1.0d - EWMA_ALPHA) + Math.log(ratio) * EWMA_ALPHA;
		return clamp(Math.exp(logNext), MIN_CORRECTION_RATIO, MAX_CORRECTION_RATIO);
	}

	private static boolean isValidSample(double value) {
		return Double.isFinite(value) && value >= 0.0d;
	}

	/**
	 * Correction ratio with both sides floored at one row: an estimate of 50 rows and an empty result yield 1/50 (one
	 * corrected row), never the clamp floor.
	 */
	private static double correctionRatio(double estimate, double actual) {
		return clamp(Math.max(1.0d, actual) / Math.max(1.0d, estimate), MIN_CORRECTION_RATIO,
				MAX_CORRECTION_RATIO);
	}

	private static double qError(double estimate, double actual) {
		if (estimate == 0.0d && actual == 0.0d) {
			return 1.0d;
		}
		if (estimate == 0.0d || actual == 0.0d) {
			return MAX_CORRECTION_RATIO;
		}
		double normalizedEstimate = Math.max(1.0d, estimate);
		double normalizedActual = Math.max(1.0d, actual);
		double ratio = Math.max(normalizedEstimate / normalizedActual, normalizedActual / normalizedEstimate);
		return clamp(ratio, 1.0d, MAX_CORRECTION_RATIO);
	}

	private static double finitePositiveOr(double value, double fallback) {
		return Double.isFinite(value) && value > 0.0d ? value : fallback;
	}

	private static double finiteQErrorOr(double value, double fallback) {
		return Double.isFinite(value) && value >= 1.0d ? value : fallback;
	}

	private static double clamp(double value, double min, double max) {
		if (!Double.isFinite(value)) {
			return min;
		}
		return Math.max(min, Math.min(max, value));
	}
}
